import assert from 'node:assert/strict';
import {mkdir,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
assert.ok(process.env.SOURCE_ROOT,'SOURCE_ROOT is required');
assert.ok(process.env.BROWSER_ARTIFACT_DIR,'BROWSER_ARTIFACT_DIR is required');
const root=resolve(process.env.SOURCE_ROOT),dir=resolve(process.env.BROWSER_ARTIFACT_DIR);
const moduleAt=path=>import(pathToFileURL(resolve(root,path)).href);
const {createProductServer}=await moduleAt('server.mjs');
const {requireChromiumSandbox}=await moduleAt('scripts/support/chromium-sandbox.mjs');
const {receiveChallengePrecision}=await moduleAt('scripts/challenge-precision.receiving.mjs');
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE||'playwright');
await mkdir(dir,{recursive:true});
const server=createProductServer();await new Promise((ok,bad)=>{server.once('error',bad);server.listen(0,'127.0.0.1',ok);});
let browser;const report=[],errors=[],external=[],badResponses=[];
try{
 browser=await chromium.launch({headless:true,chromiumSandbox:true,...(process.env.BROWSER_EXECUTABLE_PATH?{executablePath:process.env.BROWSER_EXECUTABLE_PATH}:{})});
 const context=await browser.newContext({viewport:{width:1280,height:1000},reducedMotion:'reduce'}),page=await context.newPage(),cdp=await context.newCDPSession(page);
 const send=(method,params)=>cdp.send(method,params);
 await writeFile(resolve(dir,'sandbox.json'),JSON.stringify(await requireChromiumSandbox({send}),null,2)+'\n');
 page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(!/^(http:\/\/127\.0\.0\.1:|blob:|data:)/.test(r.url()))external.push(r.url());});page.on('response',r=>{if(r.status()>=400)badResponses.push({url:r.url(),status:r.status()});});
 await page.goto('http://127.0.0.1:'+server.address().port);await page.waitForFunction(()=>document.querySelector('#sample-count')?.textContent==='64');
 const evaluate=async expression=>{const response=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(response.exceptionDetails)throw new Error(JSON.stringify(response.exceptionDetails));return response.result.value;};
 const captures=await receiveChallengePrecision({evaluate,send,report});
 for(const name of ['desktop','narrow']){assert.ok(captures[name]?.data,'Missing '+name+' capture');await writeFile(resolve(dir,'challenge-precision-'+name+'.png'),Buffer.from(captures[name].data,'base64'));}
 assert.equal(report.length,3);assert.deepEqual(errors,[]);assert.deepEqual(external,[]);assert.deepEqual(badResponses,[]);
 const receipt={browser:await browser.version(),report,errors,external,badResponses,scope:'Maintained challenge-precision receiver against actual served package with keyboard CDP actions and 1280/390px rendering. File uploads use scripted DOM File objects and export interception; this course does not claim native file chooser interaction or physical acquisition.'};
 await writeFile(resolve(dir,'receipt.json'),JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify(receipt));
}finally{await browser?.close();await new Promise(ok=>server.close(ok));}

external_receiver.chooser_source:
import assert from 'node:assert/strict';
import {mkdir,readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
assert.ok(process.env.SOURCE_ROOT,'SOURCE_ROOT is required');
assert.ok(process.env.BROWSER_ARTIFACT_DIR,'BROWSER_ARTIFACT_DIR is required');
const root=resolve(process.env.SOURCE_ROOT),dir=resolve(process.env.BROWSER_ARTIFACT_DIR);
const moduleAt=path=>import(pathToFileURL(resolve(root,path)).href);
const {createProductServer}=await moduleAt('server.mjs');
const {replaySharedTrainingCertificate}=await moduleAt('src/science/shared-training-replay.mjs');
const {requireChromiumSandbox}=await moduleAt('scripts/support/chromium-sandbox.mjs');
const {chromium}=await import(process.env.PLAYWRIGHT_MODULE||'playwright');
await mkdir(dir,{recursive:true});
const fixture={schema:'worldlaw.observations/v1',source:{label:'Authored command-law chooser fixture; synthetic rows, not independent physical acquisitions'},observations:[-1,-.5,.5,1,-1,-.5,.5,1].map(command=>({command,position:0,rate:0,jointTorque:2*command}))};
const server=createProductServer();await new Promise((ok,bad)=>{server.once('error',bad);server.listen(0,'127.0.0.1',ok);});
let browser;const errors=[],badResponses=[],external=[],checks=[];
try{
 browser=await chromium.launch({headless:true,chromiumSandbox:true,...(process.env.BROWSER_EXECUTABLE_PATH?{executablePath:process.env.BROWSER_EXECUTABLE_PATH}:{})});
 const context=await browser.newContext({viewport:{width:320,height:960},reducedMotion:'reduce'});
 const page=await context.newPage(),cdp=await context.newCDPSession(page);
 await writeFile(resolve(dir,'sandbox.json'),JSON.stringify(await requireChromiumSandbox({send:(m,p)=>cdp.send(m,p)}),null,2)+'\n');
 page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=400)badResponses.push({url:r.url(),status:r.status()});});page.on('request',r=>{if(!/^(http:\/\/127\.0\.0\.1:|blob:|data:)/.test(r.url()))external.push(r.url());});
 await page.goto('http://127.0.0.1:'+server.address().port);await page.waitForFunction(()=>document.querySelector('#sample-count').textContent==='64');
 await page.locator('#observation-file').setInputFiles({name:'chooser-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await page.waitForFunction(()=>document.querySelector('#sample-count').textContent==='8');
 for(const [id,value]of Object.entries({command:2,position:0,rate:0,'measured-torque':8}))await page.locator('#'+id).fill(String(value));
 await page.locator('#run-experiment').click();await page.waitForFunction(()=>document.querySelector('#sample-count').textContent==='9');
 const law=page.locator('#experiment-receipt-law');const options=await law.locator('option').evaluateAll(items=>items.map(x=>({value:x.value,text:x.textContent})));
 const command=options.find(x=>/^\d+\. command(?:\s|$)/.test(x.text));assert.ok(command,'Earlier command-only law is required: '+JSON.stringify(options));await law.selectOption(command.value);
 const panel=page.locator('#historical-training-receipt');
 await panel.getByRole('spinbutton',{name:'Earlier training-reading radius (N·m)',exact:true}).fill('.02');await panel.getByRole('spinbutton',{name:'Acquired reading radius (N·m)',exact:true}).fill('.01');
 const notebook=await page.evaluate(()=>localStorage.getItem('worldlaw.notebook.v1'));assert.ok(notebook);
 await panel.getByRole('button',{name:'Search shared-training evidence',exact:true}).click();assert.equal(await panel.locator('.shared-training-output').getAttribute('data-status'),'verified-separation');checks.push('Explicit historical command-law search verifies separation for synthetic eight-row training and one received row');
 const downloading=page.waitForEvent('download');await panel.getByRole('button',{name:'Export checked shared-training evidence',exact:true}).click();const certificatePath=resolve(dir,'checked-historical-separator.json');await(await downloading).saveAs(certificatePath);
 const replay=replaySharedTrainingCertificate(await readFile(certificatePath,'utf8'));assert.equal(replay.check.status,'verified-separation');checks.push('Exported certificate independently replays through the public checker');
 const input=panel.getByLabel('Replay checked shared-training evidence',{exact:true});await input.scrollIntoViewIfNeeded();await input.focus();assert.equal(await input.evaluate(n=>n===document.activeElement),true);
 const choosing=page.waitForEvent('filechooser');await page.keyboard.press('Enter');const chooser=await choosing;assert.equal(chooser.isMultiple(),false);await chooser.setFiles(certificatePath);
 await page.waitForFunction(()=>document.querySelector('#historical-training-receipt .shared-training-status').textContent.includes('Replayed by public checker: verified-separation'));
 assert.equal(await panel.locator('.shared-training-output').getAttribute('data-status'),'verified-separation');assert.deepEqual(await panel.locator('.shared-training-output li').evaluateAll(items=>items.map(n=>Number(n.dataset.value))),replay.certificate.values);
 const geometry=await input.evaluate(n=>{const r=n.getBoundingClientRect(),p=n.parentElement.getBoundingClientRect();return {left:r.left,right:r.right,width:r.width,parentLeft:p.left,parentRight:p.right,documentWidth:document.documentElement.scrollWidth,viewportWidth:innerWidth};});
 assert.equal(geometry.viewportWidth,320);assert.ok(geometry.documentWidth<=320,JSON.stringify(geometry));assert.ok(geometry.left>=0&&geometry.right<=320,JSON.stringify(geometry));assert.ok(geometry.left>=geometry.parentLeft-1&&geometry.right<=geometry.parentRight+1,JSON.stringify(geometry));
 assert.equal(await page.evaluate(()=>localStorage.getItem('worldlaw.notebook.v1')),notebook);await input.focus();await input.scrollIntoViewIfNeeded();await page.screenshot({path:resolve(dir,'historical-chooser-focused-320.png')});await panel.screenshot({path:resolve(dir,'historical-replay-panel-320.png')});
 checks.push('At 320px keyboard Enter opens the native chooser, selected certificate replays, file input fits and notebook bytes remain unchanged');
 assert.deepEqual(errors,[]);assert.deepEqual(badResponses,[]);assert.deepEqual(external,[]);
 const receipt={browser:await browser.version(),viewport:{width:320,height:960},checks,geometry,errors,badResponses,external,qualification:'Synthetic authored UI receiving course; certificate replay is mathematical evidence, not physical acquisition.'};await writeFile(resolve(dir,'receipt.json'),JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify(receipt));
}finally{await browser?.close();await new Promise(ok=>server.close(ok));}
